import{_ as t,o as a,c as _,a4 as r}from"./chunks/framework.C3unmAF4.js";const i=JSON.parse('{"title":"阿瓦提县智慧农业助力农作物丰产增收","description":"","frontmatter":{"sidebar":false,"aside":false,"editLink":false,"lastUpdated":false,"prev":false,"next":false,"title":"阿瓦提县智慧农业助力农作物丰产增收","date":"2026-07-24T00:00:00.000Z","source":"农业农村部智慧农业专题","category":"news","link":"https://www.moa.gov.cn/ztzl/zhnyzxd/xydt/202607/t20260710_6485696.htm","summary":"眼下正值“三夏”田间管理的关键时期,连日来,阿瓦提县持续推广智慧农业种植模式,以科技赋能田间管护,稳住各类作物长势,全力保障全县全年粮棉产业丰产丰收。\\n7月3日,在阿瓦提县塔木托格拉克镇托格拉克勒克村的农田里,农户们正有序查看气象与虫情监测信息,并通过无线智能网关进行手机远程滴灌。...\\n","contentHash":"3a6f9563414017019c767e2ebfdef7a3","tags":["智慧农业","行业资讯"]},"headers":[],"relativePath":"news/2026-07-24-阿瓦提县智慧农业助力农作物丰产增收.md","filePath":"news/2026-07-24-阿瓦提县智慧农业助力农作物丰产增收.md"}'),n={name:"news/2026-07-24-阿瓦提县智慧农业助力农作物丰产增收.md"};function s(o,e,p,l,d,c){return a(),_("div",null,[...e[0]||(e[0]=[r('<h1 id="阿瓦提县智慧农业助力农作物丰产增收" tabindex="-1">阿瓦提县智慧农业助力农作物丰产增收 <a class="header-anchor" href="#阿瓦提县智慧农业助力农作物丰产增收" aria-label="Permalink to &quot;阿瓦提县智慧农业助力农作物丰产增收&quot;">​</a></h1><blockquote><p>来源: <a href="https://www.moa.gov.cn/ztzl/zhnyzxd/xydt/202607/t20260710_6485696.htm" target="_blank" rel="noreferrer">农业农村部智慧农业专题</a><br> 日期: 2026-07-24 摘要: 眼下正值“三夏”田间管理的关键时期,连日来,阿瓦提县持续推广智慧农业种植模式,以科技赋能田间管护,稳住各类作物长势,全力保障全县全年粮棉产业丰产丰收。 7月3日,在阿瓦提县塔木托格拉克镇托格拉克勒克村的农田里,农户们正有序查看气象与虫情监测信息,并通过无线智能网关进行手机远程滴灌。...</p></blockquote><p>7月3日,在阿瓦提县塔木托格拉克镇托格拉克勒克村的农田里,农户们正有序查看气象与虫情监测信息,并通过无线智能网关进行手机远程滴灌。这套智慧灌溉体系可根据土壤墒情和作物需求精准输送水肥,不仅省工节水,还能保障作物长势均匀,为棉花提质增效及秋粮稳产丰收打下坚实基础。</p><p>除智能灌溉外,田间巡查与植保也实现了智能化升级。巡田无人机实时回传全景画面,帮助农户快速排查管道破损、病虫害等隐患,提升精细化管理水平;植保无人机则沿预设航线高效施药,单台每小时可作业100至150亩,大幅提升了病虫害全域防控效率。</p><p>谈及智慧种植的便利,阿瓦提县塔木托格拉克镇托格拉克勒克村种植户程自良深有体会。今年他种的2000亩地借助智慧农业设备,大幅减少了人工管护投入。水肥精细化管控让作物长势整齐,效益稳步提升。</p><p>阿瓦提县塔木托格拉克镇托格拉克勒克村种植户程自良说:“现在种地省心又高效!智能出水桩能远程控制水肥,无人机随时巡田监测,再也不用天天守在地里。精准灌溉不仅省工省料,棉花和玉米长势也更均匀了,今年我们对丰产增收的底气特别足。”</p><p>智慧农业种植模式,有效提升了农田管护精细化、科学化水平,降低农业生产劳动强度和资源消耗,持续带动农业增效、农户增收,为全县粮食安全和特色农业高质量发展提供坚实科技支撑。</p><p>“接下来,我们将持续推广良田良机良法融合模式,以科技赋能农业提质增效,夯实阿瓦提县全年粮棉等农作物丰产丰收根基。”阿瓦提县农业农村局农业技术推广中心高级工程师何重清说。(依在提古丽·胡拉木)</p><p><a href="https://www.moa.gov.cn/ztzl/zhnyzxd/xydt/202607/t20260710_6485696.htm" target="_blank" rel="noreferrer">阅读原文</a></p>',9)])])}const h=t(n,[["render",s]]);export{i as __pageData,h as default};
